/**
 * The Staff AI System Design course (`10_AI_System_Design/`) as one Learn track, T17, in the AI
 * System Design group (plan .website_spec/status/in-progress/implementation_plan_ai-system-design-course.md,
 * task SDC-05). Each stage is a module; each of the five `## ` parts of its guide is a lesson,
 * generated by `npm run import:sd-course` into 01_Concept_Tutorials/AI_System_Design_Course/. A last
 * module, Architecture decision records, holds the course's ADRs, one lesson each.
 * Titles must match the files' H1s: the import checks every file against this list.
 * Objectives and scopes come from the course's progress/curriculum-map.json; interview probes
 * are each stage's first interview question. Practice time is the lower end of the guide's study
 * budget (Stage 12's is in its stage-plan.md) less the lessons' reading time, to the nearest
 * 15 minutes; Stage 0 states no budget and gets 30 minutes for its map and checkpoints. The guides state no common mistakes, so none are listed.
 *
 * Data only: the .mjs sync scripts import this file under plain `node`.
 */
import type { CurriculumLesson, CurriculumModule, CurriculumTrack } from './curriculum-types'

const TRACK = 'staff-ai-system-design'
const ROOT = '01_Concept_Tutorials/AI_System_Design_Course'

/** The five parts every stage guide shares: lesson slug suffix and title (after the stage title). */
const PARTS = [
  ['understand-the-problem', 'understand the problem'],
  ['learn-and-design', 'learn and design'],
  ['observe-and-experiment', 'observe and experiment'],
  ['think-like-a-staff-engineer', 'think like a staff engineer'],
  ['validate-and-carry-forward', 'validate and carry forward'],
] as const

type Stage = {
  dir: string
  title: string
  section: string
  objective: string
  scope: string
  probe: string
  practiceMinutes: number
  /** Lessons elsewhere on the site that teach a concept this stage applies (their canonical homes). */
  seeAlso?: string[]
  /** Part 4 is over the page limit, so the import splits its interview questions into a lesson. */
  interviewLesson?: true
}

